    {
      "year": 10000,
      "event": "The first crewed interstellar vessel departs for a neighboring star system.",
      "detail": "A 'worldship' carrying a crew of biologically and synthetically diverse beings embarks on a multi-generational journey to colonize a new star system, marking the start of a galactic diaspora."
    }
